/** Embedded file by id (1 regular font, 2 semibold font, 3 window icon PNG). */
const unsigned char *qr_asset(int id, int *size)
{
    switch (id) {
    case 1: *size = (int)sizeof font_regular; return font_regular;
    case 2: *size = (int)sizeof font_semibold; return font_semibold;
    case 3: *size = (int)sizeof window_icon; return window_icon;
    default: *size = 0; return NULL;
    }
}
